      },
      {
        "artifact_id": "A5",
        "type": "sheet",
        "title": "MVP Backlog and Prioritisation Matrix",
        "used_for": "Lists user stories, priorities, and dependencies for the MVP scope."
      },
      {
        "artifact_id": "A6",
        "type": "guideline",
        "title": "Service Standards for On-Site Eco-Tourism Experiences",
        "used_for": "Provides partners with clear expectations for service quality and customer care."
      },
      {
        "artifact_id": "A7",
        "type": "doc",
        "title": "Go-To-Market and Channel Plan",
        "used_for": "Outlines launch messaging, campaigns, and distribution channel tactics."
      },
      {
        "artifact_id": "A8",
        "type": "sheet",
        "title": "KPI Framework and Launch Dashboard Spec",
        "used_for": "Defines KPIs, data sources, and dashboard requirements for tracking performance."
      }
    ]
  },
